(function(){'use strict';
const KEY='nawaf-hq-v5';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const PERMS=[['tasks','إنشاء وتشغيل المهام'],['projects','إدارة المشاريع'],['review','المراجعة والجودة'],['code','تعديل الكود'],['deploy','النشر والتحديث'],['external','استخدام الأدوات الخارجية']];
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason='v9-control'){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function statusAr(v){return({READY:'جاهز',IDLE:'متاح',WORKING:'يعمل',RESEARCHING:'يبحث',REVIEWING:'يراجع',WAITING_FOR_NAWAF:'بانتظارك',COMPLETED:'مكتمل',PAUSED:'متوقف'})[v]||v||'جاهز'}
function modal(html){let m=$('#v9-modal');if(!m){m=document.createElement('div');m.id='v9-modal';m.className='v9-modal';m.innerHTML='<div class="v9-dialog"><div id="v9-modal-body"></div></div>';document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m||e.target.closest('[data-v9-close]'))m.classList.remove('show')})}$('#v9-modal-body').innerHTML=html;m.classList.add('show')}
function editEmployee(id){const s=read(),e=(s.employees||[]).find(x=>x.id===id);if(!e)return;const access=Array.isArray(e.projectAccess)?e.projectAccess:[];const perms=e.permissions&&typeof e.permissions==='object'?e.permissions:{};modal(`<div class="v9-dialog-head"><div><span>EMPLOYEE CONTROL</span><h2>تعديل ${esc(e.name)}</h2><p>الاسم، الدور، المشاريع والصلاحيات من مكان واحد.</p></div><button data-v9-close>×</button></div><form id="v9-employee-form" class="v9-form"><label>الاسم<input name="name" value="${esc(e.name)}" required></label><label>المسمى الوظيفي<input name="role" value="${esc(e.role||'')}" required></label><label>القسم<input name="department" value="${esc(e.department||'')}"></label><label>الحالة<select name="status"><option value="READY" ${e.status==='READY'?'selected':''}>جاهز</option><option value="PAUSED" ${e.status==='PAUSED'?'selected':''}>متوقف</option></select></label><div class="v9-full"><b>الوصول للمشاريع</b><div class="v9-checks">${(s.projects||[]).map(p=>`<label><input type="checkbox" name="projectAccess" value="${esc(p.id)}" ${access.includes(p.id)?'checked':''}> ${esc(p.name)}</label>`).join('')}</div></div><div class="v9-full"><b>الصلاحيات</b><div class="v9-checks">${PERMS.map(([k,l])=>`<label><input type="checkbox" name="perm_${k}" ${perms[k]!==false?'checked':''}> ${l}</label>`).join('')}</div></div><div class="v9-full v9-actions"><button type="button" data-v9-close>إلغاء</button><button class="primary" type="submit">حفظ التعديلات</button></div></form>`);$('#v9-employee-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),q=read(),x=(q.employees||[]).find(v=>v.id===id);if(!x)return;x.name=String(f.get('name')||'').trim();x.role=String(f.get('role')||'').trim();x.department=String(f.get('department')||'').trim();x.status=String(f.get('status')||'READY');x.projectAccess=f.getAll('projectAccess').map(String);x.permissions={};for(const [k] of PERMS)x.permissions[k]=f.get('perm_'+k)==='on';q.activity=Array.isArray(q.activity)?q.activity:[];q.activity.unshift({id:uid('a'),text:`تم تحديث بيانات وصلاحيات ${x.name}`,type:'REAL',at:new Date().toISOString()});write(q,'employee-permissions-updated');$('#v9-modal').classList.remove('show')}}
function quickTask(){const s=read();modal(`<div class="v9-dialog-head"><div><span>QUICK COMMAND</span><h2>أمر سريع</h2><p>اختر الموظف والمشروع واكتب المهمة؛ بدون تنقل بين الصفحات.</p></div><button data-v9-close>×</button></div><form id="v9-quick-form" class="v9-form"><label>الموظف<select name="employeeId" required>${(s.employees||[]).map(e=>`<option value="${esc(e.id)}">${esc(e.name)} — ${esc(e.role||'')}</option>`).join('')}</select></label><label>المشروع<select name="projectId"><option value="">عام</option>${(s.projects||[]).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label>نوع المهمة<select name="kind"><option value="CUSTOM">تنفيذ مباشر</option><option value="RESEARCH">بحث</option><option value="REVIEW">مراجعة</option><option value="SOLVE">حل مشكلة</option></select></label><label>الأولوية<select name="priority"><option value="NORMAL">عادية</option><option value="HIGH">عالية</option><option value="URGENT">عاجلة</option></select></label><label class="v9-full">التفاصيل<textarea name="details" rows="5" required placeholder="مثال: راجع قدّها وأصلح مشكلة فتح الألعاب ثم اختبرها."></textarea></label><div class="v9-full v9-actions"><button type="button" data-v9-close>إلغاء</button><button class="primary" type="submit">▶ ابدأ المهمة</button></div></form>`);$('#v9-quick-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),q=read(),eid=String(f.get('employeeId')||''),pid=String(f.get('projectId')||''),details=String(f.get('details')||'').trim(),kind=String(f.get('kind')||'CUSTOM'),priority=String(f.get('priority')||'NORMAL');if(!details)return;const e=(q.employees||[]).find(x=>x.id===eid);if(!e)return;const task={id:uid('t'),title:details.slice(0,88),details,employeeId:eid,projectId:pid,status:'READY',progress:0,kind,priority,createdAt:new Date().toISOString(),createdBy:'NAWAF'};q.tasks=Array.isArray(q.tasks)?q.tasks:[];q.tasks.unshift(task);e.status='READY';e.task=task.title;q.activity=Array.isArray(q.activity)?q.activity:[];q.activity.unshift({id:uid('a'),text:`تكليف سريع إلى ${e.name}: ${task.title}`,type:'REAL',at:new Date().toISOString()});write(q,'quick-command');$('#v9-modal').classList.remove('show');setTimeout(()=>{if(window.NawafProjectExecutor?.scan)window.NawafProjectExecutor.scan();if(window.NawafAgents?.runTask)window.NawafAgents.runTask(task.id).catch(()=>{})},180)}}
function injectDashboard(){const main=$('.v8-main');if(!main||$('.v9-control-strip'))return;const s=read(),tasks=s.tasks||[],active=tasks.filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status)).length,waiting=tasks.filter(t=>t.status==='WAITING_FOR_NAWAF').length,urgent=tasks.filter(t=>t.priority==='URGENT'&&t.status!=='COMPLETED').length;const box=document.createElement('section');box.className='v9-control-strip';box.innerHTML=`<div class="v9-pulse"><div><span>نبض الشركة</span><b>${active}</b><small>يعمل الآن</small></div><div><span>بانتظارك</span><b>${waiting}</b><small>تحتاج قرار</small></div><div><span>عاجل</span><b>${urgent}</b><small>أولوية قصوى</small></div></div><button type="button" data-v9-quick>⚡ أمر سريع</button><button type="button" data-v9-tasks>◫ لوحة المهام</button>`;const header=main.querySelector('.v8-header');if(header)header.insertAdjacentElement('afterend',box);else main.prepend(box)}
function injectEmployeeEditors(){$$('.v8-person').forEach(card=>{if(card.dataset.v9==='1')return;card.dataset.v9='1';const id=card.getAttribute('data-employee');const b=document.createElement('button');b.type='button';b.className='v9-edit-employee';b.textContent='تعديل';b.title='تعديل الموظف والصلاحيات';b.addEventListener('click',e=>{e.stopPropagation();editEmployee(id)});card.appendChild(b)})}
function injectTaskFilters(){const rows=$$('.v8-row[data-task]');if(!rows.length||$('.v9-task-filters'))return;const host=rows[0].parentElement;if(!host)return;const f=document.createElement('div');f.className='v9-task-filters';f.innerHTML='<button class="active" data-v9-filter="ALL">الكل</button><button data-v9-filter="ACTIVE">تعمل الآن</button><button data-v9-filter="WAITING_FOR_NAWAF">بانتظارك</button><button data-v9-filter="COMPLETED">مكتملة</button><button data-v9-filter="URGENT">عاجلة</button>';host.parentElement.insertBefore(f,host);f.addEventListener('click',e=>{const b=e.target.closest('[data-v9-filter]');if(!b)return;$$('.v9-task-filters button').forEach(x=>x.classList.toggle('active',x===b));const q=read(),map=new Map((q.tasks||[]).map(t=>[t.id,t]));rows.forEach(r=>{const t=map.get(r.dataset.task),v=b.dataset.v9Filter;let show=v==='ALL'||(v==='ACTIVE'&&['WORKING','RESEARCHING','REVIEWING','READY'].includes(t?.status))||t?.status===v||(v==='URGENT'&&t?.priority==='URGENT'&&t?.status!=='COMPLETED');r.style.display=show?'':'none'})})}
function enhance(){injectDashboard();injectEmployeeEditors();injectTaskFilters()}
document.addEventListener('click',e=>{if(e.target.closest('[data-v9-quick]'))quickTask();if(e.target.closest('[data-v9-tasks]')){const b=$('[data-view="tasks"]');if(b)b.click()}});
let t;const obs=new MutationObserver(()=>{clearTimeout(t);t=setTimeout(enhance,80)});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{obs.observe(document.body,{childList:true,subtree:true});enhance()});else{obs.observe(document.body,{childList:true,subtree:true});enhance()}
window.NawafHQV9={editEmployee,quickTask,enhance};
})();